<label>Title<input name="title" value="{{ old('title', $task->title ?? '') }}" required></label><label>Description<textarea name="description">{{ old('description', $task->description ?? '') }}</textarea></label><label>Status<select name="status"><option value="pending" @selected(old('status', $task->status ?? 'pending') === 'pending')>Pending</option><option value="in_progress" @selected(old('status', $task->status ?? '') === 'in_progress')>In progress</option><option value="done" @selected(old('status', $task->status ?? '') === 'done')>Done</option></select></label><label>Due date<input type="date" name="due_date" value="{{ old('due_date', isset($task) && $task->due_date ? $task->due_date->format('Y-m-d') : '') }}"></label>
